{
  "title": "外线与负载",
  "synopsis": "林岚与周野解决墙内水管渗水危机后，迅速重接老化的外部喇叭线。但在带负载试音时，声音忽大忽小，林岚查出是长距离线路损耗导致阻抗不匹配，广播彻底修复仍差最后一步校准。",
  "preview_blurb": "水管危机刚刚解除，老化的外线又让广播站面临开天窗的风险。当试音的喇叭传出忽大忽小的怪声，真正的技术考验才刚刚开始。",
  "scenes": [
    {
      "title": "水阀与脆皮线",
      "location": "社区广播站",
      "dramatic_goal": "确认墙内水管危机解除，但立刻面临外线老化必须重接的新危机。",
      "lines": [
        {
          "kind": "narration",
          "text": "生锈的水管阀门发出刺耳的金属摩擦声，周野用力将其死死拧紧。另一边，林岚扯动外线，老化的绝缘皮发出嘶啦脆响。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "呼……墙里的水阀总算关死了，主板绝对安全！咱们赶紧通电吧？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "不行。外线老化太严重，绝缘皮一碰就碎。必须立刻重接，否则今晚广播彻底开天窗。"
        }
      ]
    },
    {
      "title": "剥线与试音",
      "location": "社区广播站",
      "dramatic_goal": "周野成功协助重接外线，但带负载试音暴露出声音不稳定的新问题。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "那我来帮忙！剥线钳给我，我保证不剪断铜芯。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "你行吗……罢了，顺着红线根部，轻轻咬合。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "咔哒。你看，铜芯完好无损！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "压接得不错。线接通了，开功放，带负载试音。"
        },
        {
          "kind": "narration",
          "text": "功放继电器清脆吸合。周野凑近麦克风，但窗外喇叭传来的声音忽大忽小，夹杂着轻微的噗噗声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "喂？老街坊们晚上好。哎？这声音怎么一阵大一阵小的？"
        }
      ]
    },
    {
      "title": "阻抗与日志",
      "location": "社区广播站",
      "dramatic_goal": "排除人为气息问题，确诊阻抗不匹配，切断电源并立下校准目标。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "是不是我离麦克风太近了？我退后点……喂？还是不行啊，难道是我气息没控制好？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "不是你的问题。别动麦克风。"
        },
        {
          "kind": "narration",
          "text": "林岚紧盯着功放表头，指针正剧烈跳动。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "长距离线路损耗太大，阻抗不匹配，输出过载了。"
        },
        {
          "kind": "narration",
          "text": "啪的一声，林岚果断切断电源，提笔在维修日志上重重写下一行字。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "带负载试音失败，音量不稳，需重新校准输出阻抗。"
        }
